begin;
do $$
declare source uuid:=gen_random_uuid(); other uuid:=gen_random_uuid(); owner_id uuid:=gen_random_uuid(); staff_id uuid:=gen_random_uuid(); recipient uuid:=gen_random_uuid(); stranger uuid:=gen_random_uuid(); r jsonb; again jsonb; target uuid; invitation_id uuid; claimed_slug text; denied boolean; count_before integer;
begin
 insert into auth.users(id,email,email_confirmed_at) values(owner_id,'source-owner@test.invalid',now()),(staff_id,'staff@test.invalid',now()),(recipient,'recipient@test.invalid',now()),(stranger,'stranger@test.invalid',now());
 insert into businesses(id,name,slug) values(source,'Source','actions-source-'||left(source::text,8)),(other,'Other','actions-other-'||left(other::text,8));
 insert into business_users(business_id,user_id,role) values(source,owner_id,'owner'),(source,staff_id,'staff');
 if can_execute_business_action(source,owner_id,'business.provision',false) then raise exception 'new capability must be disabled by default'; end if;
 if not can_execute_business_action(source,staff_id,'product.create',false) then raise exception 'legacy staff product access lost'; end if;
 insert into business_actions(business_id,action_key,enabled,monthly_limit) values(source,'business.provision',true,1);
 if not can_execute_business_action(source,owner_id,'business.provision',false) then raise exception 'owner override denied'; end if;
 if can_execute_business_action(source,staff_id,'business.provision',false) or can_execute_business_action(other,owner_id,'business.provision',false) or can_execute_business_action(source,null,'business.provision',true) then raise exception 'unexpected authority'; end if;
 insert into business_action_settings(business_id,action_key,staff_allowed,automation_allowed) values(source,'business.provision',true,true);
 if not can_execute_business_action(source,staff_id,'business.provision',false) or not can_execute_business_action(source,null,'business.provision',true) then raise exception 'settings ignored'; end if;
 update platform_actions set enabled=false where key='business.provision';
 if can_execute_business_action(source,owner_id,'business.provision',false) then raise exception 'global disable ignored'; end if;
 update platform_actions set enabled=true where key='business.provision';
 insert into action_executions(business_id,action_key,request_key,actor_id,input,status) values(source,'business.provision','manual:request-1',owner_id,'{"name":"Client Business","email":"recipient@test.invalid","description":"Prepared details"}','uncertain');
 r:=provision_business_invitation(source,owner_id,'manual:request-1','{"name":"Client Business","email":"recipient@test.invalid","description":"Prepared details"}',repeat('a',64),'ciphertext-a');
 target:=(r->>'business_id')::uuid;
 if exists(select 1 from business_users where business_id=target) then raise exception 'premature membership'; end if;
 if (select plan from business_billing where business_id=target)<>'free' then raise exception 'new business inherited paid plan'; end if;
 again:=provision_business_invitation(source,owner_id,'manual:request-1','{"name":"Client Business","email":"recipient@test.invalid","description":"Prepared details"}',repeat('b',64),'ciphertext-b');
 if again<>r or (select count(*) from action_executions where business_id=source)<>1 then raise exception 'retry duplicated business'; end if;
 denied:=false;begin perform provision_business_invitation(source,owner_id,'manual:request-1','{"name":"Different","email":"recipient@test.invalid"}',repeat('b',64),'ciphertext-b'); exception when others then denied:=sqlerrm='request_conflict';end;
 if not denied then raise exception 'request input conflict not rejected';end if;
 denied:=false;begin perform provision_business_invitation(source,owner_id,'manual:request-2','{"name":"Second","email":"recipient@test.invalid"}',repeat('c',64),'ciphertext-c');exception when others then denied:=sqlerrm='action_limit';end;
 if not denied then raise exception 'monthly limit ignored';end if;
 denied:=false;begin perform accept_business_invitation(repeat('a',64),stranger);exception when others then denied:=sqlerrm='recipient_mismatch';end;
 if not denied then raise exception 'wrong recipient claimed business';end if;
 update auth.users set email_confirmed_at=null where id=recipient;
 denied:=false;begin perform accept_business_invitation(repeat('a',64),recipient);exception when others then denied:=sqlerrm='recipient_mismatch';end;
 if not denied then raise exception 'unverified email claimed business';end if;
 update auth.users set email_confirmed_at=now() where id=recipient;
 select id into invitation_id from business_invitations where target_business_id=target;
 perform rotate_business_invitation(invitation_id,source,owner_id,repeat('d',64),'ciphertext-d',false);
 denied:=false;begin perform accept_business_invitation(repeat('a',64),recipient);exception when others then denied:=sqlerrm='invalid_invitation';end;
 if not denied then raise exception 'old token valid after rotation';end if;
 update business_invitations set expires_at=now()-interval '1 second' where id=invitation_id;
 denied:=false;begin perform accept_business_invitation(repeat('d',64),recipient);exception when others then denied:=sqlerrm='invalid_invitation';end;
 if not denied then raise exception 'expired token valid';end if;
 perform rotate_business_invitation(invitation_id,source,owner_id,repeat('e',64),'ciphertext-e',false);
 perform rotate_business_invitation(invitation_id,source,owner_id,null,null,true);
 denied:=false;begin perform accept_business_invitation(repeat('e',64),recipient);exception when others then denied:=sqlerrm='invalid_invitation';end;
 if not denied then raise exception 'revoked token valid';end if;
 perform rotate_business_invitation(invitation_id,source,owner_id,repeat('f',64),'ciphertext-f',false);
 claimed_slug:=accept_business_invitation(repeat('f',64),recipient);
 if claimed_slug is null or not exists(select 1 from business_users where business_id=target and user_id=recipient and role='owner') then raise exception 'ownership not assigned';end if;
 if accept_business_invitation(repeat('f',64),recipient)<>claimed_slug then raise exception 'accept retry failed';end if;
 if exists(select 1 from business_users where business_id=target and user_id in(owner_id,staff_id)) then raise exception 'source gained target access';end if;
 if has_function_privilege('authenticated','public.accept_business_invitation(text,uuid)','execute') then raise exception 'client can impersonate recipient';end if;
 if has_table_privilege('authenticated','public.business_invitations','select') then raise exception 'invitation secrets exposed';end if;
 update business_actions set expires_at=now()-interval '1 second' where business_id=source;
 if can_execute_business_action(source,owner_id,'business.provision',false) then raise exception 'expired entitlement valid';end if;
end $$;
do $$
declare b uuid:=gen_random_uuid(); owner_id uuid:=gen_random_uuid(); staff_id uuid:=gen_random_uuid(); conn uuid:=gen_random_uuid(); c uuid:=gen_random_uuid(); v uuid:=gen_random_uuid(); lease uuid:=gen_random_uuid(); job bigint; graph jsonb; r jsonb; denied boolean;
begin
 insert into auth.users(id,email,email_confirmed_at) values(owner_id,'workflow-owner@test.invalid',now()),(staff_id,'workflow-staff@test.invalid',now());
 insert into businesses(id,name,slug,auto_reply) values(b,'Action workflow','action-workflow-'||left(b::text,8),true);
 insert into business_users(business_id,user_id,role) values(b,owner_id,'owner'),(b,staff_id,'staff');
 insert into business_actions(business_id,action_key,enabled) values(b,'business.provision',true);
 perform save_business_action_settings(b,owner_id,'business.provision',false,true,3);
 denied:=false;begin perform save_business_action_settings(b,staff_id,'business.provision',true,true,30);exception when others then denied:=sqlerrm='unauthorized';end;
 if not denied then raise exception 'staff changed own permissions';end if;
 graph:='{"version":2,"name":"Register","nodes":[{"id":"start","kind":"start","label":"Start","position":{"x":0,"y":0},"config":{}},{"id":"action","kind":"action","label":"Prepare","position":{"x":100,"y":0},"config":{"action":{"actionKey":"business.provision","actionVersion":1,"inputs":{"name":"name","email":"email"}}}},{"id":"done","kind":"end","label":"Done","position":{"x":200,"y":0},"config":{}},{"id":"staff","kind":"handoff","label":"Staff","position":{"x":200,"y":100},"config":{}}],"edges":[{"id":"e1","source":"start","target":"action","port":"next"},{"id":"e2","source":"action","target":"done","port":"yes"},{"id":"e3","source":"action","target":"staff","port":"no"}],"flows":[{"id":"register","label":"Register","kind":"custom","entryNodeId":"action","nodeIds":["action","done","staff"]}]}';
 if not valid_visual_graph(graph,true) then raise exception 'valid action graph rejected';end if;
 if valid_visual_graph(jsonb_set(graph,'{nodes,1,config,action,actionVersion}','2'),true) then raise exception 'unknown action version accepted';end if;
 denied:=false;begin insert into visual_workflow_versions(id,business_id,graph,created_by) values(v,b,graph,staff_id);exception when others then denied:=sqlerrm='action_denied';end;
 if not denied then raise exception 'staff published privileged action';end if;
 insert into visual_workflow_versions(id,business_id,graph,created_by) values(v,b,graph,owner_id);
 insert into visual_workflows(business_id,draft,published_version_id,enabled,updated_by) values(b,graph,v,true,owner_id);
 insert into instagram_connections(id,business_id,ig_user_id,access_token_ciphertext,status) values(conn,b,'action-test-'||left(b::text,8),'test','connected');
 insert into conversations(id,business_id,channel,instagram_participant_id,instagram_connection_id,auto_reply) values(c,b,'instagram','client',conn,true);
 insert into conversation_states(conversation_id,business_id) values(c,b);
 insert into workflow_inbound_queue(business_id,channel,connection_id,participant_id,external_id,payload,status,lease_token,leased_until,conversation_id)
 values(b,'instagram',conn,'client','action-message','{}','processing',lease,now()+interval '5 minutes',c) returning id into job;
 denied:=false;begin perform provision_business_invitation(b,null,'workflow:invalid','{"name":"Client","email":"client@test.invalid"}',repeat('1',64),'encrypted',v,'action',c,null);exception when others then denied:=sqlerrm='lease_lost';end;
 if not denied then raise exception 'unguarded workflow executed';end if;
 r:=provision_business_invitation(b,null,'workflow:valid','{"name":"Client","email":"client@test.invalid"}',repeat('2',64),'encrypted',v,'action',c,jsonb_build_object('jobId',job,'leaseToken',lease,'revision',0));
 if r->>'status'<>'pending' then raise exception 'workflow result missing';end if;
 update conversations set auto_reply=false where id=c;
 denied:=false;begin perform provision_business_invitation(b,null,'workflow:paused','{"name":"Client","email":"client@test.invalid"}',repeat('3',64),'encrypted',v,'action',c,jsonb_build_object('jobId',job,'leaseToken',lease,'revision',0));exception when others then denied:=sqlerrm='ownership_lost';end;
 if not denied then raise exception 'manual takeover ignored';end if;
end $$;
rollback;
